import{_ as e,o as s,c as t,a3 as n}from"./chunks/framework.DeRSg1wr.js";const g=JSON.parse('{"title":"迁移后如何验证日志效果","description":"通过同一 traceId 和层级 spanId 验证 2.0 日志配置，不再使用 agent。","frontmatter":{"title":"迁移后如何验证日志效果","date":"2022-09-12T13:36:51.000Z","permalink":"/pages/5f1a0d/","description":"通过同一 traceId 和层级 spanId 验证 2.0 日志配置，不再使用 agent。"},"headers":[],"relativePath":"pages/5f1a0d/index.md","filePath":"10.文档/050.Javaagent方式/030.最终日志效果.md"}'),p={name:"pages/5f1a0d/index.md"};function i(d,a,l,o,c,r){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="迁移后如何验证日志效果" tabindex="-1">迁移后如何验证日志效果 <a class="header-anchor" href="#迁移后如何验证日志效果" aria-label="Permalink to &quot;迁移后如何验证日志效果&quot;">​</a></h1><p>此页面保留旧链接；TLog 2.0 的日志效果通过配置文件实现，不需要 javaagent。</p><p>给服务 A 的 HTTP 入口发送一个已知 traceId，再由 A 调用已接入 TLog 的服务 B：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;tlogTraceId: demo-request-001&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/trace-demo</span></span></code></pre></div><p>假设 A 是根入口、B 是第一次出站调用，两端日志示意为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;0&gt;&lt;demo-request-001&gt; 服务 A 开始处理请求</span></span>
<span class="line"><span>&lt;0.1&gt;&lt;demo-request-001&gt; 服务 B 处理下游调用</span></span>
<span class="line"><span>&lt;0&gt;&lt;demo-request-001&gt; 服务 A 收到结果</span></span></code></pre></div><p>A 的当前 span 仍是 <code>0</code>；子 span <code>0.1</code> 写入发往 B 的请求，由 B 的入口采用。需要同时核对真实日志前缀、MDC 与传播头，不能只看接口回传了哪个 ID。</p><p>可重复运行的跨进程 HTTP、Dubbo、网关和 MQ 验证见<a href="/guide/examples/">示例工程</a>，规则见<a href="/pages/595a3c/">SpanId</a>。</p>`,8)])])}const _=e(p,[["render",i]]);export{g as __pageData,_ as default};
